CREATE PROPERTY GRAPH OODGraph NODE TABLES (OODGraphSnapshotNodeMembershipProjection KEY (organization_id, node_membership_entry_hash) LABEL ood_graph_node PROPERTIES (organization_id, node_membership_entry_hash, graph_object_id, object_class, api_element_role, api_element_role_locator_manifest_hash, object_graph_row_hash) DYNAMIC LABEL (object_class)) EDGE TABLES (OODGraphSnapshotEdgeMembershipProjection KEY (organization_id, edge_membership_entry_hash) SOURCE KEY (organization_id, source_node_membership_entry_hash) REFERENCES OODGraphSnapshotNodeMembershipProjection (organization_id, node_membership_entry_hash) DESTINATION KEY (organization_id, target_node_membership_entry_hash) REFERENCES OODGraphSnapshotNodeMembershipProjection (organization_id, node_membership_entry_hash) LABEL ood_graph_edge PROPERTIES (organization_id, edge_membership_entry_hash, graph_edge_id, source_node_membership_entry_hash, target_node_membership_entry_hash, source_endpoint_id, target_endpoint_id, source_endpoint_class, target_endpoint_class, edge_label, edge_family, valid_from, valid_until, diagnostic_only, edge_graph_row_hash) DYNAMIC LABEL (edge_label));
